import React from 'react';import {createRoot} from 'react-dom/client';
const connection='11111111-1111-4111-8111-111111111111',calls:string[]=[];Object.assign(window,{performanceFixture:{calls}});
window.fetch=async(input,init)=>{const url=String(input),body=JSON.parse(String(init?.body));calls.push(url.split('/').pop()+':'+(body.action||'read'));if(location.search.includes('deferred')&&body.action==='connections')await new Promise<void>(resolve=>Object.assign(window,{releaseCatalog:resolve}));if(url.endsWith('/shopping-catalog')){const items=body.action==='connections'?[{id:connection,accountId:'2647636'}]:body.action==='keywordCampaigns'?[{id:'cmp-1',name:'캠페인',status:'ON'}]:body.action==='keywordGroups'?[{id:'grp-1',name:'그룹',status:'ON',bid:100}]:body.action==='keywords'?[{id:'nkw-1',name:'키워드',status:'ON',bid:100,useGroupBid:false}]:[];return Response.json({items})}return Response.json({result:{status:'observed',targetId:body.targetId,period:{since:body.since,until:body.until},observedAt:'2026-11-21T01:00:00Z',source:'naver_stats',metrics:{impressions:232,clicks:10,cost:1000,clickThroughRate:4.31,averageClickCost:100}}})};
void import('../../src/components/store/ad-performance-panel').then(({AdPerformancePanel})=>createRoot(document.getElementById('root')!).render(<AdPerformancePanel/>));
